function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 100000 values.';
  if (!Array.isArray(nums2) || nums2.length !== nums1.length) return 'nums1 and nums2 must have the same length.';
  const bad = v => !Number.isInteger(v) || v < 1 || v > 100000;
  if (nums1.some(bad) || nums2.some(bad)) return 'Every value is an integer from 1 to 100000.';
  return null;
}

