function countPairs(nums1, nums2) {
  const n = nums1.length;
  const diff = new Array(n);
  for (let i = 0; i < n; i++) {
    diff[i] = nums1[i] - nums2[i];
  }
  diff.sort((a, b) => a - b);

  let count = 0;
  let left = 0;
  let right = n - 1;
  while (left < right) {
    if (diff[left] + diff[right] > 0) {
      count += right - left;
      right--;
    } else {
      left++;
    }
  }
  return count;
}

